      SUBROUTINE LLROPS_ORTHO_EOP(TIME, DELTA_XP, DELTA_YP, DELTA_UT1)
      IMPLICIT NONE
      DOUBLE PRECISION TIME, DELTA_XP, DELTA_YP, DELTA_UT1, EOP(3)
      CALL ORTHO_EOP(TIME, EOP)
      DELTA_XP = EOP(1)
      DELTA_YP = EOP(2)
      DELTA_UT1 = EOP(3)
      RETURN
      END

      SUBROUTINE LLROPS_PMSDNUT2(RMJD, DELTA_XP, DELTA_YP)
      IMPLICIT NONE
      DOUBLE PRECISION RMJD, DELTA_XP, DELTA_YP, PM(2)
      CALL PMSDNUT2(RMJD, PM)
      DELTA_XP = PM(1)
      DELTA_YP = PM(2)
      RETURN
      END

      SUBROUTINE LLROPS_UTLIBR(RMJD, DELTA_UT1, DELTA_LOD)
      IMPLICIT NONE
      DOUBLE PRECISION RMJD, DELTA_UT1, DELTA_LOD
      CALL UTLIBR(RMJD, DELTA_UT1, DELTA_LOD)
      RETURN
      END
